def test_truncates_with_default_suffix():
    assert truncate("hello world", 8) == "hello..."


@pytest.mark.parametrize(
    ("s", "max_len", "suffix", "expected"),
    [
        ("hello world", 8, "…", "hello w…"),  # custom unicode suffix
        ("abcdef", 3, "...", "..."),          # max_len equals suffix length
        ("abcdef", 4, "", "abcd"),            # empty suffix
        ("abcdef", 0, "", ""),                # empty suffix with zero max_len
        ("😀😃😄😁", 3, "…", "😀😃…"),          # unicode input
    ],
)
def test_truncates_with_various_suffixes_and_boundaries(
